function saveCache(){try{localStorage.setItem("aix_i18n_cache",JSON.stringify(cache))}catch(e){}}
function isChinese(s){for(var i=0;i<s.length;i++){var c=s.charCodeAt(i);if((c>=0x4E00&&c<=0x9FFF)||(c>=0x3400&&c<=0x4DBF))return true}return false}
function polishEnglishText(x){if(lang!=="en")return x;return String(x).replace(new RegExp("\\n","g"),"\n").replace(/错questions/g,"mistakes").replace(/questions解析/g,"answer explanations").replace(/questions/g,"questions")}
function ownedI18nRoot(el){return el&&el.closest&&el.closest("#__aix_panel,#__aix_teacher_panel,#__aix_teacher_task_modal,#__aix_teacher_bubble,#__aix_teacher_badge")}
function collectTexts(){var texts=new Set(),w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT),n;while((n=w.nextNode())){var el=n.parentElement;if(!ownedI18nRoot(el))continue;var tag=el.tagName;if(tag==="SCRIPT"||tag==="STYLE"||tag==="TEXTAREA"||tag==="INPUT"||tag==="CODE"||tag==="SVG")continue;var t=n.textContent.trim();if(!t||t.length<2||t.length>300||!isChinese(t))continue;if(!cache[t])texts.add(t)}return[...texts]}
function i18nSkip(el){if(!el||!ownedI18nRoot(el))return true;var tag=el.tagName;return tag==="SCRIPT"||tag==="STYLE"||tag==="TEXTAREA"||tag==="INPUT"||tag==="CODE"||tag==="SVG"}function sortedKeys(map){return Object.keys(map).filter(function(k){return k&&map[k]&&map[k]!==k}).sort(function(a,b){return b.length-a.length})}function reverseCache(){var r={};for(var zh in cache){var en=cache[zh];if(en&&en!==zh&&!r[en])r[en]=zh}return r}function applyMap(map,polish){var keys=sortedKeys(map),w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT),n;while((n=w.nextNode())){var el=n.parentElement;if(i18nSkip(el))continue;var raw=n.textContent;if(!raw||!raw.trim())continue;var result=raw,changed=false;for(var i=0;i<keys.length;i++){var k=keys[i];if(result.indexOf(k)!==-1){result=result.split(k).join(map[k]);changed=true}}if(changed&&result!==raw){if(n.__aixo===undefined)n.__aixo=raw;result=polish?polish(result):result;n.__aixt=result;n.textContent=result}}}function applyCache(){if(lang==="zh")return;applyMap(cache,polishEnglishText)}
function translateAll(){if(lang==="zh")return;var uncached=collectTexts();if(!uncached.length){applyCache();return}var batch=uncached.slice(0,30);fetch(API+"/i18n/translate",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({texts:batch}),credentials:"include"}).then(function(r){return r.json()}).then(function(d){var trans=d.translations||{};for(var zh in trans){if(trans[zh]&&trans[zh]!==zh)cache[zh]=trans[zh]}saveCache();applyCache();var rem=uncached.slice(30);if(rem.length)setTimeout(translateAll,300)}).catch(function(){applyCache()})}
function restoreChinese(){var r=reverseCache();Object.assign(r,{"Learning Mentor Workbench":"学习导师工作台","LEARNING MENTOR WORKBENCH":"学习导师工作台","Learning Advisor":"学习导师","PROFILE":"学习画像","MENTOR CHAT":"导师对话","Prompt Engineering":"提示词工程","Generate STEP and check geometry":"生成步骤文件并检查几何","STEP":"步骤文件","Complete Bambu slicing":"完成拓竹切片","Define part requirements and prompt":"定义零件需求与提示词","Latest Quiz":"最近小测","CompletedStep":"完成步骤","7-day events":"近7天事件","Task reminders":"任务提醒","Weak point reminder":"薄弱知识点提醒","Expand":"展开","Close":"关闭","Send":"发送"});applyMap(r,function(x){return x})}
function applyI18nAttrs(){try{var input=document.getElementById("__aix_teacher_input");if(input)input.setAttribute("placeholder",lang==="en"?"Ask the mentor. Enter to send, Shift+Enter for a new line":"向导师提问，Enter 发送，Shift+Enter 换行")}catch(e){}}
function applyLocale(){if(lang==="en")translateAll();else restoreChinese();applyI18nAttrs()}
function switchLang(){if(lang==="zh"){lang="en";try{localStorage.setItem(LANG_KEY,"en")}catch(e){};document.documentElement.lang="en";translateAll()}else{lang="zh";try{localStorage.setItem(LANG_KEY,"zh")}catch(e){};document.documentElement.lang="zh-CN";restoreChinese()}updateLangBtn();setTimeout(applyLocale,250);setTimeout(applyLocale,900)}
var __aix_i18n_timer=null;try{new MutationObserver(function(){if(lang!=="en")return;clearTimeout(__aix_i18n_timer);__aix_i18n_timer=setTimeout(function(){applyLocale()},900)}).observe(document.body,{childList:true,subtree:true,characterData:true})}catch(e){}
