var langBtn=null
function updateLangBtn(){var label=lang==="zh"?"EN":"中";if(langBtn)langBtn.textContent=label;document.querySelectorAll("button").forEach(function(b){var t=(b.textContent||"").trim();if(b.id==="__aix_lang_toggle"||t==="EN"||t==="中"){b.textContent=label}})}
function bindLangButtons(){/* React owns the visible language controls. */}
function injectLangBtn(){if(document.getElementById("__aix_lang_toggle"))return updateLangBtn()
  var anchor=null,all=document.querySelectorAll("span,div,button,small,p,strong")
  for(var i=0;i<all.length;i++){var t=all[i].textContent||"";if((t.indexOf("student")!==-1||t.indexOf("账号")!==-1)&&t.length<30){anchor=all[i];break}}
  if(!anchor)return
  langBtn=document.createElement("button");langBtn.id="__aix_lang_toggle";langBtn.type="button";langBtn.textContent=lang==="zh"?"EN":"中"
  Object.assign(langBtn.style,{background:"transparent",color:"#94a3b8",border:"1px solid rgba(148,163,184,.25)",borderRadius:"6px",padding:"2px 7px",fontSize:"11px",fontWeight:"600",cursor:"pointer",marginLeft:"4px",fontFamily:"system-ui, sans-serif",lineHeight:"1.3",flexShrink:"0"})
  langBtn.onmouseenter=function(){langBtn.style.background="rgba(251,191,36,.12)";langBtn.style.color="#fbbf24"}
  langBtn.onmouseleave=function(){langBtn.style.background="transparent";langBtn.style.color="#94a3b8"}
  langBtn.addEventListener("click",switchLang)
  anchor.parentNode.insertBefore(langBtn,anchor)
}

// ═══════════ Auth helper ═══════════
function token(){return localStorage.getItem("aix_token")||""}
function apiFetch(path,options){var opts=options||{};opts.headers=Object.assign({Authorization:"Bearer "+token(),"Content-Type":"application/json"},opts.headers||{});return fetch(API+path,opts).then(function(r){return r.json().then(function(d){if(!r.ok)throw new Error(d.error||"API error");return d})})}

