function continueCareerEditFromOtherPage(userId,sourcePage){if(!storeCareerEditIntent(userId,sourcePage))return;window.location.assign("/personalized-secure")}
function openCareerEditConfirm(userId,sourcePage){closeCareerEditConfirm();var overlay=document.createElement("div");overlay.id=CAREER_EDIT_CONFIRM_ID;overlay.setAttribute("role","dialog");overlay.setAttribute("aria-modal","true");overlay.style.cssText="position:fixed;inset:0;z-index:10040;display:grid;place-items:center;padding:20px;background:rgba(2,8,18,.68);backdrop-filter:blur(8px)";var card=document.createElement("section");card.style.cssText="width:min(430px,94vw);border:1px solid rgba(87,227,255,.24);border-radius:20px;background:rgba(8,15,28,.98);box-shadow:0 28px 80px rgba(0,0,0,.5);padding:22px;color:#eaf3ff;font-family:Inter,system-ui,sans-serif";var title=document.createElement("h2");title.textContent=careerEditText("修改职业","Change career");title.style.cssText="margin:0;font-size:21px";var copy=document.createElement("p");copy.textContent=careerEditText("修改职业将返回职业选择页面。你当前的学习路径不会被删除。","Changing career will return you to career selection. Your current learning path will not be deleted.");copy.style.cssText="margin:12px 0 20px;color:#a9bdd6;line-height:1.65";var actions=document.createElement("div");actions.style.cssText="display:flex;justify-content:flex-end;gap:10px;flex-wrap:wrap";var cancel=document.createElement("button");cancel.type="button";cancel.textContent=careerEditText("取消","Cancel");cancel.style.cssText="border:1px solid rgba(142,163,192,.24);border-radius:12px;background:rgba(255,255,255,.04);color:#eaf3ff;padding:9px 14px;cursor:pointer";var proceed=document.createElement("button");proceed.type="button";proceed.textContent=careerEditText("继续修改职业","Continue");proceed.style.cssText="border:0;border-radius:12px;background:#c7ff4f;color:#07111f;font-weight:850;padding:9px 14px;cursor:pointer";cancel.addEventListener("click",closeCareerEditConfirm);proceed.addEventListener("click",function(){continueCareerEditFromOtherPage(userId,sourcePage)});overlay.addEventListener("click",function(e){if(e.target===overlay)closeCareerEditConfirm()});actions.appendChild(cancel);actions.appendChild(proceed);card.appendChild(title);card.appendChild(copy);card.appendChild(actions);overlay.appendChild(card);document.body.appendChild(overlay);cancel.focus()}
function requestCareerEdit(){var userId=authUserId();if(!token()||!userId)return;var sourcePage=careerEditSourcePage();if(sourcePage==="discover")dispatchCareerEdit(userId);else openCareerEditConfirm(userId,sourcePage)}
function ensureCareerEditEntry(){var account=document.querySelector(".platform-account-inline"),existing=document.getElementById(CAREER_EDIT_BUTTON_ID),userId=authUserId();if(!token()||!userId||!account){if(existing)existing.remove();closeCareerEditConfirm();return}if(existing&&existing.parentElement!==account){existing.remove();existing=null}if(!existing){existing=document.createElement("button");existing.id=CAREER_EDIT_BUTTON_ID;existing.type="button";existing.setAttribute("data-career-edit-entry","1");existing.style.cssText="border:1px solid rgba(142,163,192,.22);border-radius:10px;background:rgba(255,255,255,.04);color:#cbd5e1;width:auto;min-width:max-content;height:30px;display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto;margin-left:10px;padding:6px 10px;font-size:12px;font-weight:750;white-space:nowrap;cursor:pointer";existing.addEventListener("click",requestCareerEdit);var logout=Array.prototype.slice.call(account.querySelectorAll("button")).find(function(button){return button!==existing});account.insertBefore(existing,logout||null)}existing.textContent=careerEditText("修改职业","Change career");existing.setAttribute("aria-label",existing.textContent)}
window.addEventListener("aix-auth-changed",ensureCareerEditEntry)

