function switchTab(t){panelTab=t;var bs=document.querySelectorAll("#__aix_panel [data-ptab]");bs.forEach(function(b){if(b.getAttribute("data-ptab")===t){b.style.borderColor="#fbbf24";b.style.background="rgba(251,191,36,.1)";b.style.color="#fbbf24"}else{b.style.borderColor="#2a3050";b.style.background="transparent";b.style.color="#94a3b8"}});renderPanel()}
function renderPanel(){var body=document.getElementById("__aix_pbody");if(!body)return
  if(panelTab==="profile"){
    body.innerHTML='<div style="text-align:center;color:#94a3b8;padding:40px">读取中...</div>'
    apiFetch("/profile/me").then(function(d){var dims=d.dimensions||[],sc=d.averageQuizScore,ev=d.evidenceSummary||{}
      var DZ=["核心概念理解","工程操作判断","安全与证据意识","AI协作与Prompt能力","系统集成与调试","文档与学习习惯"]
      var DE=["Core Concepts","Engineering Judgment","Safety & Evidence","AI & Prompt","Integration & Debug","Docs & Habits"]
      var rows=DZ.map(function(l,i){var f=dims.find(function(x){return x.label===l})||{score:null,evidenceCount:0,status:"unmeasured"};return{label:l,en:DE[i],score:f.score,count:f.evidenceCount}})
      var svg='<svg width="300" height="260" viewBox="0 0 300 260" style="display:block;margin:0 auto">'
      var cx=150,cy=125,r=90
      for(var g=1;g<=5;g++){var pts=[];for(var i=0;i<6;i++){var a=-Math.PI/2+i*(Math.PI/3);pts.push((cx+Math.cos(a)*r*g*.2)+","+(cy+Math.sin(a)*r*g*.2))};svg+='<polygon points="'+pts.join(" ")+'" fill="none" stroke="rgba(148,163,184,.1)" stroke-width="1"/>'}
      for(var i=0;i<6;i++){var a=-Math.PI/2+i*(Math.PI/3);svg+='<line x1="'+cx+'" y1="'+cy+'" x2="'+(cx+Math.cos(a)*r)+'" y2="'+(cy+Math.sin(a)*r)+'" stroke="rgba(148,163,184,.12)" stroke-width="1"/>'}
      var dps=[];for(var i=0;i<6;i++){var a=-Math.PI/2+i*(Math.PI/3),s=(rows[i]?.score||0)/100;dps.push((cx+Math.cos(a)*r*s)+","+(cy+Math.sin(a)*r*s))}
      if(dps.some(function(p){return p!==cx+","+cy}))svg+='<polygon points="'+dps.join(" ")+'" fill="rgba(251,191,36,.12)" stroke="#fbbf24" stroke-width="1.5"/>'
      for(var i=0;i<6;i++){var a=-Math.PI/2+i*(Math.PI/3),s=(rows[i]?.score||0)/100,dx=cx+Math.cos(a)*r*s,dy=cy+Math.sin(a)*r*s;if(s>0)svg+='<circle cx="'+dx+'" cy="'+dy+'" r="3" fill="#fbbf24"/>'}
      for(var i=0;i<6;i++){var a=-Math.PI/2+i*(Math.PI/3),lx=cx+Math.cos(a)*118,ly=cy+Math.sin(a)*118,anchor=lx<cx-5?"end":lx>cx+5?"start":"middle";svg+='<text x="'+lx+'" y="'+ly+'" text-anchor="'+anchor+'" fill="#94a3b8" font-size="11" font-family="system-ui,sans-serif">'+(lang==="zh"?rows[i].label:rows[i].en)+'</text>'}
      svg+='</svg>'
      body.innerHTML='<div style="text-align:center;margin-bottom:16px"><h2 style="color:#fbbf24;font-size:18px;margin:0">'+(d.displayName||"学习者")+'</h2><p style="color:#64748b;font-size:12px;margin:2px 0">'+(sc!=null?"Quiz Avg "+Math.round(sc):"完成 Quiz 后形成证据")+' · '+(ev.quizAttempts||0)+' 次提交</p></div>'+svg+'<div style="margin-top:12px">'+rows.map(function(r){return'<div style="display:flex;align-items:center;padding:6px 10px;margin-bottom:3px;background:rgba(30,37,69,.4);border-radius:6px"><span style="width:140px;font-size:12px;color:#cbd5e1">'+(lang==="zh"?r.label:r.en)+'</span><div style="flex:1;height:5px;background:#1e2545;border-radius:3px;margin:0 10px"><div style="height:100%;background:linear-gradient(90deg,#fbbf24,#f59e0b);border-radius:3px;width:'+(r.score||0)+'%"></div></div><span style="width:36px;text-align:right;font-size:12px;color:'+(r.score!=null?'#fbbf24':'#64748b')+'">'+(r.score!=null?r.score:'-')+'</span></div>'}).join("")+'</div><div style="margin-top:10px;padding:10px 12px;background:rgba(251,191,36,.05);border:1px solid rgba(251,191,36,.15);border-radius:8px;font-size:11px;color:#64748b;line-height:1.6">维度得分 = 答对题数 ÷ 总答题数 × 100% · 全部来自 Quiz 提交 · ≥3条=已测量</div>'
    }).catch(function(){body.innerHTML='<div style="text-align:center;padding:40px;color:#94a3b8">需要登录后才能查看</div>'})
  }else if(panelTab==="twin"){
    body.innerHTML='<div style="text-align:center;color:#94a3b8;padding:40px">读取中...</div>'
    apiFetch("/profile/digital-twin").then(function(d){if(!d.twin){body.innerHTML='<div style="text-align:center;padding:40px;color:#94a3b8"><p style="margin-bottom:16px">尚未生成数字分身</p><button onclick="window.__aix_genTwin()" style="padding:10px 28px;background:linear-gradient(135deg,#fbbf24,#f59e0b);color:#000;border:0;border-radius:10px;font-weight:700;cursor:pointer;font-size:14px">生成数字分身</button></div>';return}
      body.innerHTML='<div style="background:rgba(30,37,69,.3);border-radius:12px;padding:16px;font-size:14px;line-height:1.7;color:#cbd5e1;white-space:pre-wrap">'+(d.twin.content||"")+'</div>'
    }).catch(function(){body.innerHTML='<div style="text-align:center;padding:40px;color:#94a3b8">读取失败</div>'})
  }else if(panelTab==="quiz"){
    body.innerHTML='<div style="text-align:center;color:#94a3b8;padding:40px">读取中...</div>'
    apiFetch("/quizzes?limit=20&offset=0").then(function(d){var items=d.items||[];if(!items.length){body.innerHTML='<div style="text-align:center;padding:40px;color:#94a3b8">暂无做题记录</div>';return}
      body.innerHTML='<div style="font-size:13px;color:#64748b;margin-bottom:12px">共 '+(d.total||items.length)+' 条</div>'+items.map(function(item){return'<div style="display:flex;align-items:center;padding:12px;margin-bottom:6px;background:rgba(30,37,69,.3);border-radius:8px"><div style="flex:1"><strong style="color:#cbd5e1">'+(item.title||"Quiz").replace(/</g,"&lt;")+'</strong><br><small style="color:#64748b">'+(item.phase||"")+' · '+(item.questionCount||0)+' questions</small></div><span style="font-size:16px;font-weight:700;color:'+(item.scorePercent>=80?'#22c55e':item.scorePercent>=50?'#fbbf24':'#ef4444')+'">'+(item.scorePercent!=null?item.scorePercent+'%':'-')+'</span></div>'}).join("")
    }).catch(function(){body.innerHTML='<div style="text-align:center;padding:40px;color:#94a3b8">暂无做题记录</div>'})
  }
}

// ═══════════ DT Generate ═══════════
window.__aix_genTwin=function(){
  var body=document.getElementById("__aix_pbody");if(!body)return
  body.innerHTML='<div style="text-align:center;color:#94a3b8;padding:40px">正在生成数字分身...</div>'
  apiFetch("/profile/digital-twin",{method:"POST",body:"{}"}).then(function(){
    apiFetch("/profile/digital-twin").then(function(d){
      if(!d.twin){body.innerHTML='<div style="text-align:center;padding:40px;color:#94a3b8">生成失败，请先完成一些课程和 Quiz</div>';return}
      body.innerHTML='<div style="background:rgba(30,37,69,.3);border-radius:12px;padding:16px;font-size:14px;line-height:1.7;color:#cbd5e1;white-space:pre-wrap">'+(d.twin.content||"")+'</div>'
    })
  }).catch(function(err){body.innerHTML='<div style="text-align:center;padding:40px;color:#94a3b8">生成失败: '+err.message+'</div>'})
}



// Digital Teacher: learning advisor layer
var teacherState={data:null,lastFetch:0}
var teacherTab="alerts",teacherChat=[],teacherGuardStarted=false,teacherGuardTimer=null
function escHtml(s){return String(s==null?"":s).replace(/[&<>"']/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]})}
function priorityColor(p){return p==="high"?"#c7ff4f":p==="medium"?"#57e3ff":"#8ea3c0"}
function readTeacherIds(){try{return JSON.parse(localStorage.getItem("aix_teacher_read_ids")||"[]")}catch(e){return[]}}
function writeTeacherIds(ids){try{localStorage.setItem("aix_teacher_read_ids",JSON.stringify(ids.slice(-80)))}catch(e){}}
function isTeacherRead(id){return readTeacherIds().indexOf(id)>=0}
function markTeacherRead(id){if(!id)return;var ids=readTeacherIds();if(ids.indexOf(id)<0){ids.push(id);writeTeacherIds(ids)}updateTeacherBadge()}
function teacherLayerAdvice(){var d=teacherState.data||{},s=d.summary||{},weak=s.weakKnowledge||[],quiz=s.latestQuiz||{},ev=s.eventSummary7d||{};var score=Number(quiz.scorePercent);if(!Number.isFinite(score))score=65;var weakScore=weak.length?Number(weak[0].score||70):80;var completed=Number(ev.stepCompletions||0),check=Number(ev.checklistUpdates||0);var level='标准层',why='最近表现处在可继续推进区间，需要保留关键检查点。',next='按当前 Step 完成操作、证据和一次自检。';if(score<60||weakScore<50){level='详细层';why='最近 Quiz 或薄弱知识点显示基础链条不稳，容易在相似步骤重复出错。';next='下一步会增加检查点、完成标准和错因复盘。'}else if(score>=85&&completed>=3&&check>=3){level='简略层';why='最近完成速度和证据记录较稳定，可以减少过程提示。';next='下一步保留目标和验收标准，减少中间提示。'}return{level:level,why:why,next:next,score:score,weakScore:weakScore}}
function teacherEvidenceText(){var d=teacherState.data||{},s=d.summary||{},ev=s.eventSummary7d||{},quiz=s.latestQuiz||{},weak=s.weakKnowledge||[],agent=s.recentAgentQuestions||[];var arr=[];if(quiz&&quiz.scorePercent!=null)arr.push('最近一次 Quiz 得分 '+Math.round(Number(quiz.scorePercent))+'%，错题会影响后续 Step 的细化程度。');if(weak.length)arr.push('当前最需要巩固的是“'+weak[0].label+'”，掌握度偏低。');if(Number(ev.stepCompletions||0)>0||Number(ev.checklistUpdates||0)>0)arr.push('最近 7 天有 '+(ev.stepCompletions||0)+' 次步骤完成记录、'+(ev.checklistUpdates||0)+' 次清单记录。');if(agent.length)arr.push('最近向助教提过问题，可转成举一反三练习。');if(!arr.length)arr.push('当前证据还不多，先完成一个 Step 和一次 Quiz，我再给你更准确的判断。');return arr}
function derivedTeacherItems(){var d=teacherState.data||{},s=d.summary||{},weak=s.weakKnowledge||[],quiz=s.latestQuiz||null,ev=s.eventSummary7d||{},agent=s.recentAgentQuestions||[];var slot=Math.floor(Date.now()/1800000),out=[];function pct(v){v=Number(v);return Number.isFinite(v)?Math.round(v):null}if(quiz&&pct(quiz.scorePercent)!=null){var sc=pct(quiz.scorePercent);out.push({id:'quiz-review-'+slot+'-'+(quiz.quizId||quiz.id||sc),type:'quiz_review',priority:sc<60?'high':(sc<85?'medium':'low'),title:sc<85?'复盘最近 Quiz 错题':'快速确认最近 Quiz',summary:(sc<85?'最近 Quiz 得分 '+sc+'%。建议先复盘错题，再决定是否重做。':'最近 Quiz 表现不错，用 2 分钟确认可迁移点。'),action:'查看错题复盘',payload:{quizId:quiz.quizId||quiz.id,score:sc}})}if(weak.length){var w=weak[0]||{};out.push({id:'weak-point-'+slot+'-'+String(w.label||'weak').slice(0,24),type:'weak_point',priority:(Number(w.score)||100)<50?'high':'medium',title:'薄弱知识点提醒',summary:'“'+(w.label||'薄弱知识点')+'”会影响后续学习。先看概念补丁，不直接做题。',action:'查看概念补丁',payload:{weak:w}})}out.push({id:'spaced-review-'+slot,type:'spaced_review',priority:'medium',title:'间隔复习计划',summary:(weak[0]?'“'+weak[0].label+'”':'最近错题知识点')+'适合按今天、明天、3 天后做短复习。',action:'查看复习计划',payload:{weak:weak[0]||null}});var total=Number(ev.total||0),done=Number(ev.stepCompletions||0),check=Number(ev.checklistUpdates||0);if(total>=8){out.push({id:'pace-'+slot,type:'pace_check',priority:(done<3||check<3)?'medium':'low',title:'学习节奏提醒',summary:(done<3||check<3)?'最近学习行为不少，但完成记录或清单偏少。建议先补证据。':'最近推进稳定，可以保持当前节奏。',action:'查看节奏建议',payload:{total:total,done:done,check:check}})}if(agent.length){out.push({id:'agent-challenge-'+slot,type:'agent_challenge',priority:'low',title:'举一反三挑战',summary:'把最近问过的问题转成一个小挑战，检验能不能迁移到新情境。',action:'开始挑战',payload:{question:agent[0]}})}return out.slice(0,5)}
function unreadTeacherItems(){var d=teacherState.data||{},items=(d.notifications||[]).concat(derivedTeacherItems());return items.filter(function(x){return x&&x.type!=="step_layer"&&x.type!=="step_reason"&&!isTeacherRead(x.id)})}
