  var badge=fab.querySelector("#__aix_teacher_badge");Object.assign(badge.style,{position:"absolute",right:"-3px",top:"-4px",minWidth:"18px",height:"18px",borderRadius:"999px",background:"#c7ff4f",color:"#07111f",fontSize:"11px",fontWeight:"800",display:"none",alignItems:"center",justifyContent:"center",border:"1px solid rgba(7,17,31,.5)"})
  var drag=null,clamp=function(v,min,max){return Math.min(max,Math.max(min,v))}
  fab.addEventListener("pointerdown",function(e){if(e.button&&e.button!==0)return;var r=fab.getBoundingClientRect();drag={sx:e.clientX,sy:e.clientY,ox:r.left,oy:r.top,m:false};e.preventDefault()})
  window.addEventListener("pointermove",function(e){if(!drag)return;if(Math.abs(e.clientX-drag.sx)+Math.abs(e.clientY-drag.sy)>3)drag.m=true;fab.style.left=clamp(drag.ox+e.clientX-drag.sx,4,window.innerWidth-62)+"px";fab.style.top=clamp(drag.oy+e.clientY-drag.sy,4,window.innerHeight-62)+"px"},{passive:false})
