function ensureTeacherFab(){try{var old=document.getElementById("__aix_fab_profile");if(old)old.remove();if(document.body&&!document.getElementById("__aix_teacher_fab"))createTeacherFab()}catch(e){}}
function updateTeacherBadge(){var b=document.getElementById("__aix_teacher_badge");if(!b)return;var n=unreadTeacherItems().length;if(n){b.style.display="flex";b.textContent=String(Math.min(99,n));b.title="有 "+n+" 条未读学习任务"}else{b.style.display="none";b.textContent=""}}
