function showTeacherBubble(){if(document.getElementById("__aix_teacher_panel"))return;var n=teacherTopNotification();if(!n)return;var old=document.getElementById("__aix_teacher_bubble");if(old)old.remove();var fab=document.getElementById("__aix_teacher_fab");if(!fab)return;var r=fab.getBoundingClientRect();var bubble=document.createElement("div");bubble.id="__aix_teacher_bubble";var w=300;var left=r.left<window.innerWidth/2?Math.min(window.innerWidth-w-12,r.right+10):Math.max(12,r.left-w-10);var top=Math.min(window.innerHeight-136,Math.max(12,r.top-8));bubble.style.cssText="position:fixed;left:"+left+"px;top:"+top+"px;z-index:897;width:"+w+"px;background:rgba(10,18,32,.97);border:1px solid rgba(87,227,255,.25);border-radius:18px;box-shadow:0 18px 46px rgba(0,0,0,.44);padding:13px 14px;color:#e5f0ff;font-family:system-ui,sans-serif";bubble.innerHTML='<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px"><div style="min-width:0"><div style="font-size:12px;color:#57e3ff;font-weight:850;letter-spacing:.08em">新任务提醒</div><div style="font-weight:900;font-size:14px;line-height:1.4;margin-top:4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+escHtml(n.title)+'</div><div style="font-size:12px;line-height:1.55;color:#9fb1c8;margin-top:5px">'+escHtml(n.summary||"点击查看任务详情")+'</div></div><button data-close="1" style="border:0;background:transparent;color:#8ea3c0;font-size:16px;cursor:pointer">×</button></div><div style="display:flex;gap:8px;margin-top:12px"><button data-open="1" style="border:0;border-radius:12px;background:#c7ff4f;color:#07111f;font-weight:900;padding:8px 12px;cursor:pointer">打开任务</button><button data-list="1" style="border:1px solid rgba(87,227,255,.26);border-radius:12px;background:rgba(87,227,255,.06);color:#bfefff;font-weight:850;padding:8px 12px;cursor:pointer">最近任务</button></div>';document.body.appendChild(bubble);bubble.querySelector('[data-close]').onclick=function(){bubble.remove()};bubble.querySelector('[data-open]').onclick=function(){bubble.remove();openTeacherTaskModal(n)};bubble.querySelector('[data-list]').onclick=function(){bubble.remove();teacherTab="alerts";openTeacherPanel("alerts")};setTimeout(function(){if(document.body.contains(bubble))bubble.remove()},16000)}
function refreshTeacher(showBubble){if(!token())return;var now=Date.now();if(now-teacherState.lastFetch<8000&&teacherState.data){updateTeacherBadge();if(showBubble)showTeacherBubble();return}teacherState.lastFetch=now;apiFetch("/digital-teacher/context").then(function(d){teacherState.data=d;updateTeacherBadge();if(showBubble){var top=teacherTopNotification(),last=0,lastId="";try{last=Number(localStorage.getItem("aix_teacher_bubble_seen")||0);lastId=String(localStorage.getItem("aix_teacher_bubble_seen_id")||"")}catch(e){};if(top&&(top.id!==lastId||Date.now()-last>45*1000)){try{localStorage.setItem("aix_teacher_bubble_seen",String(Date.now()));localStorage.setItem("aix_teacher_bubble_seen_id",String(top.id||""))}catch(e){};setTimeout(showTeacherBubble,700)}}}).catch(function(){})}
