function openTeacherPanel(tab){var b=document.getElementById("__aix_teacher_bubble");if(b)b.remove();var old=document.getElementById("__aix_teacher_panel");if(old)old.remove();teacherTab=tab||teacherTab||"alerts";var panel=document.createElement("div");panel.id="__aix_teacher_panel";panel.style.cssText="position:fixed;left:88px;bottom:28px;z-index:9997;width:min(520px,calc(100vw - 32px));max-height:min(760px,88vh);background:rgba(8,15,28,.98);border:1px solid rgba(87,227,255,.24);border-radius:22px;box-shadow:0 32px 90px rgba(0,0,0,.56);color:#e5f0ff;overflow:hidden;font-family:system-ui,sans-serif";panel.innerHTML='<div style="display:flex;align-items:center;padding:17px 19px;border-bottom:1px solid rgba(142,163,192,.14)"><div><div style="font-size:12px;color:#57e3ff;letter-spacing:.12em;text-transform:uppercase;font-weight:800">Learning Advisor</div><div style="font-size:19px;font-weight:900;margin-top:2px">AI 学习导师</div></div><button id="__aix_teacher_close" style="margin-left:auto;border:0;background:transparent;color:#8ea3c0;font-size:22px;cursor:pointer">×</button></div><div id="__aix_teacher_tabs" style="display:flex;gap:6px;padding:12px 14px;border-bottom:1px solid rgba(142,163,192,.12)"></div><div id="__aix_teacher_body" style="padding:18px;overflow:auto;max-height:calc(min(760px,88vh) - 124px)"><div style="color:#8ea3c0">读取中...</div></div>';document.body.appendChild(panel);positionTeacherPanel(panel);panel.querySelector("#__aix_teacher_close").onclick=function(){panel.remove()};renderTeacherTabs();renderTeacherPanel();setTimeout(function(){positionTeacherPanel(panel)},0);setTimeout(function(){positionTeacherPanel(panel)},450);refreshTeacher(false)}
function positionTeacherPanel(panel){var fab=document.getElementById("__aix_teacher_fab");if(!fab||!panel)return;var r=fab.getBoundingClientRect(),w=panel.offsetWidth||520,h=panel.offsetHeight||Math.min(760,window.innerHeight*.88),gap=12;var left=r.left<window.innerWidth/2?r.right+gap:r.left-w-gap;left=Math.max(16,Math.min(left,window.innerWidth-w-16));var top=r.top;top=Math.max(16,Math.min(top,window.innerHeight-h-16));panel.style.left=left+"px";panel.style.top=top+"px";panel.style.bottom="auto";panel.style.pointerEvents="auto";panel.style.visibility="visible"}
function renderTeacherTabs(){var box=document.getElementById("__aix_teacher_tabs");if(!box)return;var tabs=[['alerts','提醒'],['profile','画像'],['records','答题记录'],['plan','学习计划'],['chat','向导师提问']];box.innerHTML=tabs.map(function(t){var active=teacherTab===t[0];return'<button data-ttab="'+t[0]+'" style="border:1px solid '+(active?'rgba(199,255,79,.55)':'rgba(142,163,192,.18)')+';background:'+(active?'rgba(199,255,79,.12)':'rgba(16,27,45,.6)')+';color:'+(active?'#c7ff4f':'#8ea3c0')+';border-radius:999px;padding:7px 12px;font-weight:800;font-size:12px;cursor:pointer">'+t[1]+'</button>'}).join('');box.querySelectorAll('[data-ttab]').forEach(function(btn){btn.onclick=function(){teacherTab=btn.getAttribute('data-ttab');renderTeacherTabs();renderTeacherPanel()}})}
