function actionPrompt(n){var t=n&&n.type;if(t==="quiz_review")return"请根据我最近一次 Quiz 的错题，给我一份 5 分钟复盘清单，并出 3 道客观巩固题。";if(t==="review_due"||t==="spaced_review")return"请按照间隔复习的思路，帮我复习现在最该回顾的知识点，并给出一个很短的复习任务。";if(t==="learning_habit")return"我最近求助比较多，请把当前学习步骤拆成更清晰的排错顺序。";if(t==="agent_memory")return"请结合我最近问过 Agent 的问题，判断我真正卡在哪里，并给一个下一步建议。";return"请根据我的学习记录，给我一个现在最应该执行的小任务。"}







function teacherTaskTitle(n){var t=n&&n.type||"";if(t.indexOf("quiz")>=0)return "错题复盘";if(t.indexOf("spaced")>=0)return "间隔复习计划";if(t.indexOf("weak")>=0)return "薄弱知识点提醒";if(t.indexOf("pace")>=0||t.indexOf("habit")>=0)return "学习节奏提醒";if(t.indexOf("agent_challenge")>=0||t.indexOf("agent")>=0)return "举一反三挑战";return "学习任务"}
function teacherTaskWeak(){var s=(teacherState.data&&teacherState.data.summary)||{},arr=[];(s.weakKnowledge||[]).forEach(function(w){if(w&&w.label)arr.push(w.label)});var q=s.latestQuiz||{};(q.weakTags||[]).forEach(function(w){if(w&&arr.indexOf(w)<0)arr.push(w)});if(!arr.length)arr=["当前课程核心概念","工程排错流程","证据链记录"];return arr.slice(0,4)}
function teacherTaskQuestions(n){var w=teacherTaskWeak(),main=w[0]||"当前知识点",second=w[1]||"操作证据";return[{type:"single",stem:"围绕“"+main+"”做复盘时，最能帮助定位问题根因的第一步是什么？",options:["直接换一个方案继续尝试","先复述目标、现象和已验证证据","只查看最终答案是否正确","跳过报错细节，进入下一课"],answer:[1],explain:"先把目标、现象和证据拆清楚，才能判断是概念误解、操作遗漏，还是环境问题。"},{type:"multiple",stem:"哪些做法能让“"+second+"”相关问题更容易被导师或同伴复现？",options:["记录具体时间点和操作步骤","保留关键截图或日志","只写一句‘还是不行’","说明已尝试过的排查动作"],answer:[0,1,3],explain:"可复现的证据链通常包含时间、步骤、现象、日志/截图和已尝试操作。"},{type:"judge",stem:"复盘时只记正确答案、不解释错误原因，也能稳定迁移到后续任务。",options:["对","错"],answer:[1],explain:"错题巩固的重点是解释错误原因和迁移条件，否则很容易在相似场景再次出错。"},{type:"single",stem:"如果后续 Step 再次出现“"+main+"”相关任务，当前画像更应该如何调整学习路径？",options:["保持完全相同的简略步骤","增加关键检查点和完成标准","直接跳过相关 Step","只让导师给出答案"],answer:[1],explain:"薄弱知识点再次出现时，Step 应增加检查点、完成标准和必要提示，而不是替代学生完成。"}]}
function openTeacherTaskModal(n){try{markTeacherRead(n&&n.id)}catch(e){}var panel=document.getElementById("__aix_teacher_panel");if(panel)panel.remove();var old=document.getElementById("__aix_teacher_task_modal");if(old)old.remove();var m=document.createElement("div");m.id="__aix_teacher_task_modal";m.style.cssText="position:fixed;inset:0;z-index:10020;background:rgba(2,8,18,.62);backdrop-filter:blur(10px);display:flex;align-items:center;justify-content:center;padding:18px;font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#eaf3ff";var card=document.createElement("div");card.style.cssText="width:min(760px,94vw);max-height:min(760px,88vh);overflow:auto;border:1px solid rgba(87,227,255,.22);border-radius:24px;background:linear-gradient(180deg,rgba(13,25,43,.98),rgba(7,14,27,.98));box-shadow:0 28px 80px rgba(0,0,0,.46);padding:22px";card.innerHTML='<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:14px;margin-bottom:18px"><div><div style="font-size:12px;letter-spacing:.16em;color:#57e3ff;text-transform:uppercase">Learning Task</div><div style="font-size:24px;font-weight:900;margin-top:6px">'+escHtml(teacherTaskTitle(n))+'</div><div style="font-size:13px;color:#9fb1c8;line-height:1.65;margin-top:7px">这是导师提醒触发的独立任务。自由提问请回到导师对话；这里只处理复盘、巩固和计划。</div></div><button data-close="1" style="border:1px solid rgba(142,163,192,.24);background:rgba(255,255,255,.04);color:#dbeafe;border-radius:13px;padding:8px 12px;cursor:pointer;font-weight:800">关闭</button></div><div id="__aix_teacher_task_body"></div>';m.appendChild(card);document.body.appendChild(m);m.addEventListener("click",function(e){if(e.target===m||e.target.getAttribute("data-close")){m.remove();renderTeacherBubble()}});renderTeacherTaskBody(card.querySelector("#__aix_teacher_task_body"),n)}

