function renderTeacherLearningPlan(body){body.innerHTML='<div style="color:#8ea3c0">读取学习计划中...</div>';function table(plan){var rows=plan&&Array.isArray(plan.rows)?plan.rows:[];if(!plan||!rows.length){body.innerHTML='<div style="border:1px solid rgba(142,163,192,.16);border-radius:16px;padding:16px;background:rgba(16,27,45,.52);color:#9fb1c8;line-height:1.7"><div style="font-weight:900;color:#eaf3ff;margin-bottom:6px">暂无执行中的学习计划</div><div>在“间隔复习计划”任务里点击“执行这个计划”后，计划会显示在这里。新的 Quiz、错题和学习记录会继续生成新的计划建议，你可以随时替换执行。</div></div>';return}body.innerHTML='<div style="border:1px solid rgba(199,255,79,.18);background:rgba(199,255,79,.055);border-radius:16px;padding:14px;margin-bottom:12px"><div style="font-size:12px;color:#8ea3c0">当前执行计划</div><div style="font-size:20px;font-weight:950;margin-top:4px">'+escHtml(plan.title||'间隔复习计划')+'</div><div style="font-size:13px;color:#b9c8dc;margin-top:6px">复习重点：'+escHtml(plan.focusLabel||plan.focus||'最近错题知识点')+'</div><div style="font-size:12px;color:#8ea3c0;margin-top:6px">'+escHtml((plan.createdAt||plan.created_at||'').replace('T',' ').slice(0,19))+'</div></div><div style="border:1px solid rgba(142,163,192,.16);border-radius:18px;overflow:hidden"><table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr style="background:rgba(87,227,255,.08);color:#bfefff"><th style="text-align:left;padding:12px">时间</th><th style="text-align:left;padding:12px">复习动作</th><th style="text-align:left;padding:12px">完成标准</th></tr></thead><tbody>'+rows.map(function(r){return '<tr style="border-top:1px solid rgba(142,163,192,.12)"><td style="padding:12px;color:#eaf3ff;font-weight:800">'+escHtml(r.time||'')+'</td><td style="padding:12px;color:#cbd8ea">'+escHtml(r.action||'')+'</td><td style="padding:12px;color:#9fb1c8">'+escHtml(r.standard||'')+'</td></tr>'}).join('')+'</tbody></table></div><div style="margin-top:12px;color:#8ea3c0;font-size:12px;line-height:1.6">说明：任务提醒会继续根据新的学习记录、Quiz 和错题变化推送。如果你在新的“间隔复习计划”中选择执行，这里会替换为最新计划。</div>'}apiFetch('/teacher-learning-plans?limit=1').then(function(d){var items=d.items||[];if(items.length)table(items[0]);else{var local=[];try{local=JSON.parse(localStorage.getItem('aix_teacher_learning_plans')||'[]')}catch(e){}table(local[0])}}).catch(function(){var local=[];try{local=JSON.parse(localStorage.getItem('aix_teacher_learning_plans')||'[]')}catch(e){}table(local[0])})}
function renderTeacherTaskBody(body,n){var t=n&&n.type||"",weak=teacherTaskWeak(),layer=teacherLayerAdvice();function card(title,txt,color){return '<div style="border:1px solid rgba(142,163,192,.16);border-left:3px solid '+(color||'#57e3ff')+';border-radius:16px;padding:13px 14px;background:rgba(16,27,45,.58);margin-bottom:10px"><div style="font-weight:900;color:#eaf3ff;margin-bottom:6px">'+escHtml(title)+'</div><div style="font-size:13px;line-height:1.65;color:#b9c8dc">'+txt+'</div></div>'}if(t.indexOf("quiz")>=0){body.innerHTML=card('任务目标','复盘最近 Quiz 的错题。先看错因，再决定是否重做一组巩固题。','#c7ff4f')+card('要求','1. 先说出至少一个错因。<br>2. 点击下方按钮后才开始巩固题。<br>3. 提交后记录会进入“答题记录”。','#57e3ff')+'<button data-start-drill="1" style="margin-top:8px;border:0;border-radius:14px;background:#c7ff4f;color:#07111f;font-weight:900;padding:11px 15px;cursor:pointer">开始错题重做</button>';body.querySelector('[data-start-drill]').onclick=function(){renderTeacherTaskDrill(body,n,'错题重做')};return}if(t.indexOf("weak")>=0){var main=weak[0]||'当前薄弱知识点';body.innerHTML=card('薄弱知识点',escHtml(main),'#c7ff4f')+card('为什么提醒你','这个点在最近 Quiz 或学习画像中不稳定，后续 Step 可能会再次用到。','#57e3ff')+card('你要做什么','用自己的话复述这个概念，并在当前 Step 中找一个对应的操作证据。完成后可回到导师对话继续问。','#fbbf24')+'<button data-mark-done="1" style="margin-top:8px;border:1px solid rgba(199,255,79,.35);border-radius:14px;background:rgba(199,255,79,.08);color:#c7ff4f;font-weight:900;padding:10px 14px;cursor:pointer">我已看完概念补丁</button>';body.querySelector('[data-mark-done]').onclick=function(){body.innerHTML+=card('已记录','这条提醒已完成。它不会生成答题记录，因为这里不是题目任务。','#c7ff4f')};return}if(t.indexOf("spaced")>=0||t.indexOf("review")>=0){var main2=weak[0]||'最近错题知识点';var rows=teacherPlanRows(main2);body.innerHTML=card('复习对象',escHtml(main2),'#c7ff4f')+'<div style="border:1px solid rgba(142,163,192,.16);border-radius:18px;overflow:hidden"><table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr style="background:rgba(87,227,255,.08);color:#bfefff"><th style="text-align:left;padding:12px">时间</th><th style="text-align:left;padding:12px">复习动作</th><th style="text-align:left;padding:12px">完成标准</th></tr></thead><tbody>'+rows.map(function(r){return '<tr style="border-top:1px solid rgba(142,163,192,.12)"><td style="padding:12px;color:#eaf3ff;font-weight:800">'+escHtml(r.time)+'</td><td style="padding:12px;color:#cbd8ea">'+escHtml(r.action)+'</td><td style="padding:12px;color:#9fb1c8">'+escHtml(r.standard)+'</td></tr>'}).join('')+'</tbody></table></div><div style="margin-top:12px;color:#9fb1c8;font-size:13px">这个任务只做计划和提醒，不生成题目。你可以选择是否执行；执行后会放入“学习计划”栏。</div><button data-use-plan="1" style="margin-top:12px;border:0;border-radius:14px;background:#c7ff4f;color:#07111f;font-weight:900;padding:11px 15px;cursor:pointer">执行这个计划</button>';body.querySelector('[data-use-plan]').onclick=function(){var plan=buildTeacherLearningPlan(n);var btn=body.querySelector('[data-use-plan]');if(btn){btn.disabled=true;btn.textContent='保存计划中...'}saveTeacherLearningPlan(plan,function(){teacherTab='plan';var modal=document.getElementById('__aix_teacher_task_modal');if(modal)modal.remove();openTeacherPanel('plan')})};return}if(t.indexOf("agent_challenge")>=0||t.indexOf("agent")>=0){body.innerHTML=card('挑战目标','把最近向 Agent 问过的问题迁移到新情境，检验是否真的理解。','#57e3ff')+card('要求','完成 4 道客观题。提交后记录会进入“答题记录”。','#c7ff4f')+'<button data-start-drill="1" style="margin-top:8px;border:0;border-radius:14px;background:#c7ff4f;color:#07111f;font-weight:900;padding:11px 15px;cursor:pointer">开始举一反三挑战</button>';body.querySelector('[data-start-drill]').onclick=function(){renderTeacherTaskDrill(body,n,'举一反三')};return}body.innerHTML=card('节奏判断',escHtml((n&&n.summary)||'最近学习节奏需要看一下。'),'#57e3ff')+card('建议选择','如果你觉得卡住：放慢并使用详细层。<br>如果你觉得太简单：保持标准层，完成 Quiz 后再升级简略层。<br>如果清单没完成：先补证据再进入下一步。','#c7ff4f')+'<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:12px"><button data-choice="slow" style="border:1px solid rgba(87,227,255,.25);border-radius:12px;background:rgba(87,227,255,.07);color:#bfefff;padding:10px;font-weight:850">放慢一点</button><button data-choice="keep" style="border:1px solid rgba(199,255,79,.25);border-radius:12px;background:rgba(199,255,79,.07);color:#c7ff4f;padding:10px;font-weight:850">保持节奏</button><button data-choice="fast" style="border:1px solid rgba(251,191,36,.25);border-radius:12px;background:rgba(251,191,36,.07);color:#fbbf24;padding:10px;font-weight:850">挑战简略层</button></div>';body.querySelectorAll('[data-choice]').forEach(function(btn){btn.onclick=function(){body.innerHTML+=card('已记录选择','你的节奏选择已在本次界面中记录。后续仍以 Quiz 和学习证据综合判断。','#c7ff4f')}})}
function saveTeacherAttempt(n,qs,answers,score,total,label){var detail={taskId:n&&n.id,taskType:n&&n.type,title:teacherTaskTitle(n),label:label||teacherTaskTitle(n),score:score,total:total,questions:qs.map(function(q,qi){var selected=answers[qi]||[];var right=selected.slice().sort().join(',')===q.answer.slice().sort().join(',');return{stem:q.stem,type:q.type,options:q.options,userAnswer:selected.map(function(i){return String.fromCharCode(65+i)}),correctAnswer:q.answer.map(function(i){return String.fromCharCode(65+i)}),correct:right,analysis:q.explain,tags:teacherTaskWeak().slice(0,2)}}),createdAt:new Date().toISOString()};try{var old=JSON.parse(localStorage.getItem('aix_teacher_attempts')||'[]');old.unshift(detail);localStorage.setItem('aix_teacher_attempts',JSON.stringify(old.slice(0,30)))}catch(e){}apiFetch('/teacher-task-attempts',{method:'POST',body:JSON.stringify(detail)}).catch(function(){})}
function renderTeacherTaskDrill(body,n,label){var qs=teacherTaskQuestions(n);body.innerHTML='<div style="display:grid;gap:14px">'+qs.map(function(q,qi){var type=q.type==="multiple"?"多选":q.type==="judge"?"判断":"单选";return '<div data-q="'+qi+'" style="border:1px solid rgba(142,163,192,.16);border-radius:18px;background:rgba(16,27,45,.66);padding:15px"><div style="display:flex;gap:10px;align-items:flex-start"><span style="font-size:12px;border-radius:999px;background:rgba(87,227,255,.12);color:#bfefff;padding:4px 8px;font-weight:850">'+type+'</span><div style="font-weight:900;line-height:1.55">'+(qi+1)+'. '+escHtml(q.stem)+'</div></div><div style="display:grid;gap:8px;margin-top:12px">'+q.options.map(function(o,oi){var input=q.type==="multiple"?"checkbox":"radio";return '<label style="display:flex;gap:10px;align-items:center;border:1px solid rgba(142,163,192,.14);border-radius:14px;padding:10px 12px;cursor:pointer;background:rgba(2,8,18,.24)"><input name="teacher_task_q_'+qi+'" type="'+input+'" value="'+oi+'"><span>'+escHtml(String.fromCharCode(65+oi)+'. '+o)+'</span></label>'}).join('')+'</div><div data-explain="'+qi+'" style="display:none;margin-top:10px;font-size:13px;line-height:1.6;color:#9fb1c8"></div></div>'}).join('')+'</div><button data-submit-task="1" style="margin-top:16px;border:0;border-radius:15px;background:#c7ff4f;color:#07111f;font-weight:950;padding:12px 18px;cursor:pointer">提交并查看结果</button>';body.querySelector('[data-submit-task]').onclick=function(){var ok=0,answers={};qs.forEach(function(q,qi){var selected=Array.from(body.querySelectorAll('[name="teacher_task_q_'+qi+'"]')).filter(function(i){return i.checked}).map(function(i){return Number(i.value)});answers[qi]=selected;var ans=q.answer.slice().sort().join(',');var right=selected.slice().sort().join(',')===ans;if(right)ok++;var ex=body.querySelector('[data-explain="'+qi+'"]');if(ex){ex.style.display='block';ex.innerHTML='<div style="color:'+(right?'#c7ff4f':'#ff9e9e')+';font-weight:900;margin-bottom:4px">'+(right?'回答正确':'需要复盘')+'</div><div>你的答案：'+(selected.length?selected.map(function(i){return String.fromCharCode(65+i)}).join('、'):'未作答')+'</div><div>正确答案：'+q.answer.map(function(i){return String.fromCharCode(65+i)}).join('、')+'</div><div>'+escHtml(q.explain)+'</div>'}});saveTeacherAttempt(n,qs,answers,ok,qs.length,label);var result=document.createElement('div');result.style.cssText='margin-top:14px;border:1px solid rgba(199,255,79,.24);background:rgba(199,255,79,.08);border-radius:16px;padding:13px;color:#eaf3ff;font-weight:900';result.textContent='本次答题结果：'+ok+'/'+qs.length+'。记录已保存到“答题记录”。';body.querySelector('[data-submit-task]').replaceWith(result)}}

