function renderTeacherAlerts(body,d){var s=d.summary||{},items=unreadTeacherItems(),quiz=s.latestQuiz,weak=s.weakKnowledge||[],agent=s.recentAgentQuestions||[];window.__aix_teacher_task_items=items;var taskList=items.length?'<div style="display:grid;gap:9px">'+items.map(function(n,i){return '<button data-teacher-task-index="'+i+'" style="width:100%;text-align:left;border:1px solid rgba(142,163,192,.16);border-left:3px solid '+priorityColor(n.priority)+';background:rgba(16,27,45,.72);border-radius:14px;padding:12px 13px;cursor:pointer;color:#eaf3ff"><div style="display:flex;justify-content:space-between;gap:10px;align-items:center"><div style="font-size:14px;font-weight:900">'+escHtml(n.title||("任务 "+(i+1)))+'</div><span style="font-size:11px;color:#8ea3c0">打开</span></div><div style="font-size:12px;line-height:1.55;color:#9fb1c8;margin-top:5px">'+escHtml(n.summary||"查看学习任务详情")+'</div></button>'}).join('')+'</div>':'<div style="border:1px solid rgba(142,163,192,.14);border-radius:14px;padding:16px;color:#9fb1c8;background:rgba(16,27,45,.5)">当前没有新的任务消息。完成课程、Quiz 或检查清单后，导师会自动生成下一条提醒。</div>';var weakTop=weak.slice(0,3);var judgement=weakTop.length?weakTop.map(function(w,i){var score=Math.max(0,Math.min(100,Number(w.score)||0));var level=score<50?'优先补':'继续巩固';return '<div style="border:1px solid rgba(87,227,255,.14);border-radius:14px;padding:11px 12px;background:rgba(8,15,28,.38)"><div style="display:flex;justify-content:space-between;gap:10px;align-items:center"><div style="font-size:13px;font-weight:900;color:#eaf3ff;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+(i+1)+'. '+escHtml(w.label||'薄弱知识点')+'</div><span style="font-size:12px;color:'+(score<50?'#ffb4b4':'#fbbf24')+';font-weight:900">'+level+'</span></div><div style="height:6px;background:#132033;border-radius:99px;overflow:hidden;margin:8px 0"><div style="height:100%;width:'+Math.max(4,score)+'%;background:'+(score<50?'#ff9e9e':'#fbbf24')+'"></div></div><div style="font-size:12px;line-height:1.55;color:#9fb1c8"><b style="color:#dbeafe">原因</b>：最近 Quiz 或学习证据显示这个点不稳定。<br><b style="color:#dbeafe">下一步</b>：先回看错题解析，再做 1 个同类迁移题。</div></div>'}).join(''):'<div style="color:#9fb1c8;font-size:13px">暂无明显薄弱点。可以继续推进当前课程。</div>';body.innerHTML='<div style="display:grid;grid-template-columns:1fr;gap:10px;margin-bottom:14px"><div style="border:1px solid rgba(199,255,79,.18);background:rgba(199,255,79,.06);border-radius:14px;padding:12px"><div style="color:#8ea3c0;font-size:12px">最近 Quiz</div><div style="font-size:20px;font-weight:900;margin-top:3px">'+(quiz&&quiz.scorePercent!=null?quiz.scorePercent+"%":"暂无")+'</div></div></div><div style="font-weight:900;margin:2px 0 9px">最近任务</div>'+taskList+'<div style="margin-top:14px;border:1px solid rgba(87,227,255,.16);border-radius:16px;background:rgba(16,27,45,.52);padding:13px"><div style="font-weight:900;margin-bottom:10px">导师判断</div><div style="display:grid;gap:8px">'+judgement+'</div><div style="margin-top:10px;font-size:12px;color:#8ea3c0">最近对话：'+(agent.length?escHtml(agent[0].text):"暂无")+'</div></div>';body.querySelectorAll('[data-teacher-task-index]').forEach(function(btn){btn.onclick=function(){var n=(window.__aix_teacher_task_items||[])[Number(btn.getAttribute('data-teacher-task-index'))];openTeacherTaskModal(n)}})}
function teacherDimensions(d){var s=d.summary||{},ev=s.eventSummary7d||{},quiz=s.latestQuiz,weak=s.weakKnowledge||[],agent=s.recentAgentQuestions||[],rec=s.recentRecommendations||[];var weakAvg=weak.length?weak.reduce(function(a,w){return a+(Number(w.score)||0)},0)/weak.length:78;var quizScore=quiz&&quiz.scorePercent!=null?Number(quiz.scorePercent):65;var total=Number(ev.total||0),help=Number(ev.helpRequests||0),completed=Number(ev.stepCompletions||0),check=Number(ev.checklistUpdates||0),opened=Number(ev.routeStepOpened||0),quizN=Number(ev.quizSubmissions||0);function cap(x){return Math.max(5,Math.min(100,Math.round(x)))}return[{label:'概念掌握稳定度',score:cap(quizScore*.55+weakAvg*.45),basis:'综合最近 Quiz 得分和薄弱知识点掌握度。'},{label:'工程排错成熟度',score:cap(55+check*6-help*8+(quizScore-60)*.25),basis:'参考检查清单、求助次数和错题表现，判断排错是否有顺序。'},{label:'学习推进效率',score:cap(45+completed*12+opened*3+quizN*5),basis:'参考课程打开、步骤完成和 Quiz 提交，判断推进是否顺畅。'},{label:'自主提问质量',score:cap(45+agent.length*10-help*3),basis:'参考与 Agent 的主动提问数量和求助模式。'},{label:'证据与安全意识',score:cap(45+check*10+(total?Math.min(20,total*.8):0)),basis:'参考检查清单、学习证据和安全相关行为。'},{label:'复盘迁移能力',score:cap(quizScore*.4+(100-Math.max(0,60-weakAvg))*.25+quizN*8+(rec.length?8:0)),basis:'参考错题复盘、间隔复习触发和 Step 分层更新。'}]}
function radarSvg(vals){var shortLabels=["概念稳定","工程排错","推进效率","提问质量","证据安全","复盘迁移"];var labels=vals.map(function(v,i){return shortLabels[i]||v.label}),scores=vals.map(function(v){return Math.max(5,Math.min(100,v.score))});var cx=180,cy=145,r=78,n=labels.length;var pts=scores.map(function(sc,i){var a=-Math.PI/2+i*2*Math.PI/n;var rr=r*sc/100;return[cx+Math.cos(a)*rr,cy+Math.sin(a)*rr]});var axes=labels.map(function(lb,i){var a=-Math.PI/2+i*2*Math.PI/n;var x=cx+Math.cos(a)*r,y=cy+Math.sin(a)*r;var tx=cx+Math.cos(a)*(r+58),ty=cy+Math.sin(a)*(r+42);return '<line x1="'+cx+'" y1="'+cy+'" x2="'+x+'" y2="'+y+'" stroke="rgba(142,163,192,.22)"/><text x="'+tx+'" y="'+ty+'" text-anchor="middle" dominant-baseline="middle" fill="#9fb1c8" font-size="11" font-weight="700">'+escHtml(lb)+'</text>'}).join('');var rings=[.33,.66,1].map(function(k){var p=[];for(var i=0;i<n;i++){var a=-Math.PI/2+i*2*Math.PI/n;p.push((cx+Math.cos(a)*r*k)+','+(cy+Math.sin(a)*r*k))}return '<polygon points="'+p.join(' ')+'" fill="none" stroke="rgba(142,163,192,.16)"/>'}).join('');return '<svg viewBox="0 0 360 310" style="width:100%;max-width:420px;display:block;margin:0 auto 12px;overflow:visible">'+rings+axes+'<polygon points="'+pts.map(function(p){return p[0]+','+p[1]}).join(' ')+'" fill="rgba(199,255,79,.20)" stroke="#c7ff4f" stroke-width="2"/><circle cx="'+cx+'" cy="'+cy+'" r="3" fill="#57e3ff"/></svg>'}


function openTeacherQuizDetail(item){item=item||{};var old=document.getElementById("__aix_teacher_quiz_detail");if(old)old.remove();var m=document.createElement("div");m.id="__aix_teacher_quiz_detail";m.style.cssText="position:fixed;inset:0;z-index:10030;background:rgba(2,8,18,.62);backdrop-filter:blur(10px);display:flex;align-items:center;justify-content:center;padding:18px;color:#eaf3ff;font-family:Inter,system-ui,sans-serif";document.body.appendChild(m);m.addEventListener("click",function(e){if(e.target===m||e.target.getAttribute("data-close"))m.remove()});function render(data,loading){data=data||item;var qs=data.questions||data.questionResults||(data.detail&&data.detail.items)||(data.report&&data.report.items)||data.answers||data.details||[];var score=data.scorePercent;if(score==null)score=data.percentage;if(score==null)score=data.score;if(score==null)score=data.bestScore;var body='';if(loading){body='<div style="border:1px solid rgba(142,163,192,.16);border-radius:14px;padding:14px;background:rgba(16,27,45,.58);color:#9fb1c8">正在读取逐题详情...</div>'}else if(Array.isArray(qs)&&qs.length){body=qs.map(function(q,i){var stem=q.stem||q.question||q.title||("题目 "+(i+1));var user=q.userAnswer||q.selected||q.answerGiven||q.user_answer||q.userAnswerText||"-";var ans=q.correctAnswer||q.answer||q.correct_answer||q.correctAnswerText||"-";var exp=q.analysis||q.explain||q.explanation||q.reason||"";var right=q.correct===true||q.isCorrect===true||String(user)===String(ans);return '<div style="border:1px solid rgba(142,163,192,.14);border-radius:14px;padding:12px;background:rgba(16,27,45,.58);margin-bottom:10px"><div style="font-weight:900;margin-bottom:7px">'+(i+1)+'. '+escHtml(stem)+'</div><div style="font-size:12px;color:'+(right?'#c7ff4f':'#ff9e9e')+';font-weight:850;margin-bottom:5px">'+(right?'回答正确':'需要复盘')+'</div><div style="font-size:12px;color:#9fb1c8;line-height:1.7">你的答案：'+escHtml(Array.isArray(user)?user.join("、"):String(user))+'<br>正确答案：'+escHtml(Array.isArray(ans)?ans.join("、"):String(ans))+'</div>'+(exp?'<div style="margin-top:8px;font-size:12px;line-height:1.65;color:#dbeafe">'+escHtml(exp)+'</div>':'')+'</div>'}).join('')}else{body='<div style="border:1px solid rgba(142,163,192,.16);border-radius:14px;padding:14px;background:rgba(16,27,45,.58);color:#9fb1c8;line-height:1.7">这条 Quiz 记录已保留，但当前详情接口没有返回逐题答案和解析。</div>'}m.innerHTML='<div style="width:min(760px,94vw);max-height:min(760px,88vh);overflow:auto;border:1px solid rgba(87,227,255,.22);border-radius:24px;background:linear-gradient(180deg,rgba(13,25,43,.98),rgba(7,14,27,.98));box-shadow:0 28px 80px rgba(0,0,0,.46);padding:22px"><div style="display:flex;justify-content:space-between;gap:12px;align-items:flex-start;margin-bottom:16px"><div><div style="font-size:12px;color:#57e3ff;font-weight:850;letter-spacing:.08em">Quiz Detail</div><div style="font-size:22px;font-weight:950;margin-top:5px">'+escHtml(data.title||"Quiz 详情")+'</div><div style="font-size:13px;color:#9fb1c8;margin-top:5px">'+escHtml(data.phase||"")+' · '+(data.questionCount||0)+' 题 · '+(score!=null?score+'%':'已完成')+'</div></div><button data-close="1" style="border:1px solid rgba(142,163,192,.24);background:rgba(255,255,255,.04);color:#dbeafe;border-radius:13px;padding:8px 12px;cursor:pointer;font-weight:800">关闭</button></div>'+body+'</div>'}render(item,true);if(item.quizId){apiFetch("/quizzes/"+encodeURIComponent(item.quizId)).then(function(d){render(d,false)}).catch(function(){render(item,false)})}else render(item,false)}

function renderTeacherQuizRecords(){var box=document.getElementById("__aix_teacher_quiz_records");if(!box)return;apiFetch("/quizzes?limit=6&offset=0&status=SUBMITTED").then(function(d){var items=d.items||[];if(!items.length){box.innerHTML='<div style="display:flex;align-items:center;justify-content:space-between;gap:10px"><div><div style="font-size:13px;color:#bde56c;font-weight:850">最近 Quiz 记录</div><div style="font-size:12px;color:#8ea3c0;margin-top:3px">暂无做题记录。完成一次 Quiz 后会保留在这里。</div></div><div style="font-size:12px;color:#8ea3c0">0 条</div></div>';return}window.__aix_teacher_quiz_items=items;box.innerHTML='<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px"><div><div style="font-size:13px;color:#bde56c;font-weight:850">最近 Quiz 记录</div><div style="font-size:12px;color:#8ea3c0;margin-top:3px">点击任意一条查看答题详情。</div></div><div style="font-size:12px;color:#8ea3c0">共 '+(d.total||items.length)+' 条</div></div><div style="display:grid;gap:8px">'+items.map(function(item,idx){var score=item.scorePercent;if(score==null)score=item.percentage;if(score==null)score=item.score;if(score==null)score=item.bestScore;var hasScore=score!=null&&score!==''&&!isNaN(Number(score));if(hasScore)score=Math.round(Number(score));var clr=hasScore?(score>=80?'#c7ff4f':score>=50?'#fbbf24':'#ff9e9e'):'#8ea3c0';return '<button data-quiz-detail="'+idx+'" style="width:100%;box-sizing:border-box;text-align:left;display:grid;grid-template-columns:minmax(0,1fr) 58px;align-items:center;gap:10px;border:1px solid rgba(142,163,192,.13);border-radius:13px;background:rgba(8,15,28,.42);padding:10px 11px;cursor:pointer;color:#eaf3ff;overflow:hidden"><div style="min-width:0;overflow:hidden"><div style="font-size:13px;font-weight:850;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+escHtml(item.title||"Quiz")+'</div><div style="font-size:11px;color:#8ea3c0;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+escHtml(item.phase||"")+' · '+(item.questionCount||0)+' 题 · 查看详情</div></div><div style="justify-self:end;max-width:58px;min-width:48px;text-align:center;border-radius:999px;padding:5px 6px;background:rgba(255,255,255,.04);font-size:'+(hasScore?'15px':'11px')+';font-weight:950;color:'+clr+'">'+(hasScore?score+'%':'已完成')+'</div></button>'}).join('')+'</div>';box.querySelectorAll('[data-quiz-detail]').forEach(function(btn){btn.onclick=function(){var item=(window.__aix_teacher_quiz_items||[])[Number(btn.getAttribute('data-quiz-detail'))];openTeacherQuizDetail(item)}})}).catch(function(){box.innerHTML='<div style="display:flex;align-items:center;justify-content:space-between;gap:10px"><div><div style="font-size:13px;color:#bde56c;font-weight:850">最近 Quiz 记录</div><div style="font-size:12px;color:#8ea3c0;margin-top:3px">暂时读取不到做题记录。</div></div><div style="font-size:12px;color:#8ea3c0">读取失败</div></div>'})}

function renderTeacherAnswerRecords(body){body.innerHTML='<div id="__aix_teacher_quiz_records" style="border:1px solid rgba(199,255,79,.18);background:rgba(199,255,79,.055);border-radius:16px;padding:14px;margin-bottom:12px"><div style="display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px"><div><div style="font-size:13px;color:#bde56c;font-weight:850">最近 Quiz 记录</div><div style="font-size:12px;color:#8ea3c0;margin-top:3px">保留最近做题结果，方便回看错题和薄弱点。</div></div><div style="font-size:12px;color:#8ea3c0">读取中...</div></div></div><div id="__aix_teacher_task_records"><div style="color:#8ea3c0">读取巩固题与错题重做记录中...</div></div>';renderTeacherQuizRecords();var target=document.getElementById('__aix_teacher_task_records');function draw(items){if(!target)return;if(!items||!items.length){target.innerHTML='<div style="font-weight:900;margin:12px 0 10px">巩固题 / 错题重做</div><div style="border:1px solid rgba(142,163,192,.16);border-radius:16px;padding:16px;color:#9fb1c8;background:rgba(16,27,45,.5)">暂无巩固题或错题重做记录。完成相关任务后会显示在这里。</div>';return}target.innerHTML='<div style="font-weight:900;margin:12px 0 10px">巩固题 / 错题重做</div><div style="display:grid;gap:10px">'+items.map(function(x,i){var sc=x.score!=null&&x.total?Math.round(Number(x.score)/Number(x.total)*100):null;return '<div style="border:1px solid rgba(142,163,192,.15);border-radius:15px;padding:12px;background:rgba(16,27,45,.58)"><div style="display:flex;justify-content:space-between;gap:10px"><div style="font-weight:900;color:#eaf3ff;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+escHtml(x.label||x.title||x.taskType||'答题记录')+'</div><div style="flex:0 0 auto;color:'+(sc>=80?'#c7ff4f':sc>=60?'#fbbf24':'#ff9e9e')+';font-weight:950">'+(sc!=null?sc+'%':'已完成')+'</div></div><div style="font-size:12px;color:#8ea3c0;margin-top:4px">'+escHtml((x.createdAt||x.created_at||'').replace('T',' ').slice(0,19))+' · '+(x.score||0)+'/'+(x.total||0)+'</div><div style="margin-top:8px;font-size:12px;color:#b9c8dc;line-height:1.6">'+((x.questions||[]).slice(0,2).map(function(q){return (q.correct?'✓ ':'× ')+escHtml(q.stem||'题目')}).join('<br>')||'记录已保存')+'</div></div>'}).join('')+'</div>'}apiFetch('/teacher-task-attempts?limit=20').then(function(d){draw(d.items||[])}).catch(function(){var local=[];try{local=JSON.parse(localStorage.getItem('aix_teacher_attempts')||'[]')}catch(e){}draw(local)})}
function renderTeacherProfile(body,d){var vals=teacherDimensions(d),s=d.summary||{},weak=s.weakKnowledge||[],ev=s.eventSummary7d||{};body.innerHTML='<div style="border:1px solid rgba(87,227,255,.16);background:rgba(16,27,45,.66);border-radius:16px;padding:14px;margin-bottom:12px"><div style="font-size:13px;color:#8ea3c0;margin-bottom:8px">学习状态雷达图</div>'+radarSvg(vals)+'<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:8px">'+vals.map(function(x){return '<div title="'+escHtml(x.basis)+'" style="border:1px solid rgba(142,163,192,.13);border-radius:11px;padding:8px;background:rgba(8,15,28,.45)"><div style="font-size:11px;color:#8ea3c0">'+escHtml(x.label)+'</div><div style="font-size:17px;font-weight:900">'+x.score+'%</div></div>'}).join('')+'</div></div><div style="font-weight:850;margin:12px 0 8px">薄弱知识点</div>'+(weak.length?weak.slice(0,8).map(function(w){return '<div style="display:flex;align-items:center;gap:10px;margin-bottom:8px"><div style="flex:1;color:#cbd5e1;font-size:13px">'+escHtml(w.label)+'</div><div style="width:110px;height:7px;background:#152238;border-radius:99px;overflow:hidden"><div style="height:100%;width:'+Math.max(4,w.score)+'%;background:#c7ff4f"></div></div><div style="width:38px;text-align:right;color:#8ea3c0;font-size:12px">'+w.score+'%</div></div>'}).join(''):'<div style="color:#8ea3c0;font-size:13px">暂无明显薄弱点。</div>')+'<div style="font-weight:850;margin:16px 0 8px">近 7 天学习证据</div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px">'+[['事件',ev.total||0],['完成',ev.stepCompletions||0],['求助',ev.helpRequests||0],['清单',ev.checklistUpdates||0],['Quiz',ev.quizSubmissions||0],['打开课程',ev.routeStepOpened||0]].map(function(x){return '<div style="border:1px solid rgba(142,163,192,.14);border-radius:12px;padding:10px;background:rgba(16,27,45,.5)"><div style="font-size:11px;color:#8ea3c0">'+x[0]+'</div><div style="font-size:18px;font-weight:900">'+x[1]+'</div></div>'}).join('')+'</div>'}
function cleanTutorText(t){return String(t||'').replace(/\*\*/g,'').replace(/^\s*[-*_]{3,}\s*$/gm,'').replace(/^\s*#{1,6}\s*/gm,'').replace(/\n{3,}/g,'\n\n').trim()}
function formatTutorAnswer(t){t=cleanTutorText(t);if(!t)return'';function strong(s){return escHtml(s).replace(/(建议|重点|下一步|原因|结论|薄弱|错题|复习|优先|完成标准|注意)/g,'<strong style="color:#eaf3ff">$1</strong>')}var lines=t.split(/\n+/).map(function(x){return x.trim()}).filter(Boolean);var html=[],table=[];function flushTable(){if(table.length<2){table.forEach(function(r){html.push('<div style="border:1px solid rgba(142,163,192,.12);background:rgba(16,27,45,.55);border-radius:12px;padding:9px 11px;margin:7px 0;font-size:13px;line-height:1.68;color:#dbeafe">'+strong(r.join(' ｜ '))+'</div>')});table=[];return}html.push('<table style="width:100%;border-collapse:separate;border-spacing:0;margin:8px 0;border:1px solid rgba(87,227,255,.18);border-radius:12px;overflow:hidden;font-size:12px;color:#dbeafe"><tbody>'+table.map(function(r,i){return '<tr>'+r.map(function(c){return '<td style="padding:9px 10px;border-top:'+(i?'1px solid rgba(142,163,192,.12)':'0')+';background:'+(i?'rgba(16,27,45,.5)':'rgba(87,227,255,.08)')+';font-weight:'+(i?'500':'850')+'">'+strong(c)+'</td>'}).join('')+'</tr>'}).join('')+'</tbody></table>');table=[]}lines.forEach(function(line){var raw=line.replace(/^[-•]\s*/,'').trim();if(raw.indexOf('|')>=0){var cells=raw.split('|').map(function(x){return x.trim()}).filter(Boolean);if(cells.length>=2){table.push(cells);return}}flushTable();var important=/建议|下一步|薄弱|错题|Quiz|复习|优先|完成标准|结论|原因/.test(raw);html.push('<div style="border:'+(important?'1px solid rgba(199,255,79,.22)':'1px solid rgba(142,163,192,.12)')+';border-left:'+(important?'3px solid #c7ff4f':'1px solid rgba(142,163,192,.12)')+';background:'+(important?'rgba(199,255,79,.06)':'rgba(16,27,45,.55)')+';border-radius:12px;padding:9px 11px;margin:7px 0;font-size:13px;line-height:1.68;color:#dbeafe">'+strong(raw)+'</div>')});flushTable();return html.join('')}
function renderTeacherChat(body){var msgs=teacherChat.map(function(m){var isUser=m.role==='user',html=isUser?escHtml(m.text):formatTutorAnswer(m.text);return'<div style="margin:10px 0;display:flex;justify-content:'+(isUser?'flex-end':'flex-start')+'"><div style="max-width:'+(isUser?'78%':'88%')+';border:1px solid '+(isUser?'rgba(199,255,79,.22)':'rgba(87,227,255,.18)')+';background:'+(isUser?'rgba(199,255,79,.14)':'rgba(16,27,45,.72)')+';border-radius:'+(isUser?'18px 18px 6px 18px':'18px 18px 18px 6px')+';padding:12px 14px;font-size:13px;line-height:1.75;color:#e6f0ff;white-space:'+(isUser?'pre-wrap':'normal')+';box-shadow:'+(isUser?'none':'0 10px 28px rgba(0,0,0,.12)')+'">'+html+'</div></div>'}).join('');body.innerHTML='<div id="__aix_teacher_chatlog" style="min-height:250px;max-height:420px;overflow:auto;margin-bottom:14px;padding-right:4px">'+(msgs||'<div style="color:#a9bdd6;font-size:13px;line-height:1.8;border:1px solid rgba(87,227,255,.16);border-radius:18px;padding:16px;background:rgba(16,27,45,.58)"><div style="font-weight:900;color:#eaf3ff;margin-bottom:6px">可以直接和我聊学习问题。</div><div>比如：我最近哪里薄弱？下一步先做什么？能不能根据错题给我出几道巩固题？</div></div>')+'</div><div style="display:flex;gap:10px;align-items:stretch;border:1px solid rgba(142,163,192,.16);background:rgba(8,15,28,.72);border-radius:18px;padding:8px"><textarea id="__aix_teacher_input" placeholder="向导师提问，Enter 发送，Shift+Enter 换行" style="flex:1;min-height:44px;max-height:120px;resize:none;border:0;background:transparent;color:#e5f0ff;padding:8px 10px;font-family:system-ui,sans-serif;font-size:13px;line-height:1.55;outline:none"></textarea><button id="__aix_teacher_send" style="align-self:stretch;border:0;border-radius:14px;background:#c7ff4f;color:#07111f;font-weight:950;padding:0 18px;cursor:pointer">发送</button></div>';var log=body.querySelector('#__aix_teacher_chatlog');if(log)log.scrollTop=log.scrollHeight;var input=body.querySelector('#__aix_teacher_input'),send=body.querySelector('#__aix_teacher_send');function submit(){var v=(input.value||'').trim();if(!v)return;input.value='';sendTeacherQuestion(v,false)}send.onclick=submit;input.onkeydown=function(e){if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();submit()}};setTimeout(function(){try{input.focus()}catch(e){}},40)}
function localTeacherReply(text){var q=String(text||'');var d=teacherState.data||{},s=d.summary||{},weak=s.weakKnowledge||[],quiz=s.latestQuiz||{},ev=s.eventSummary7d||{},layer=teacherLayerAdvice();function topWeak(){return weak.length?weak.slice(0,3).map(function(w,i){return (i+1)+'. '+w.label+'（掌握度约 '+w.score+'%）'}).join('\n'):'目前没有明显薄弱点，建议先完成当前 Step 和一次 Quiz。'}if(/最近|学得|状态|怎么样/.test(q))return '结论：你现在处在“'+layer.level+'推进”状态。\n原因：'+teacherEvidenceText().join('\n')+'\n下一步：'+layer.next;if(/哪里|薄弱|弱点|不会/.test(q))return '重点薄弱点：\n'+topWeak()+'\n建议：先选第 1 个薄弱点做错题复盘，再做 1 道变式题。';if(/下一步|怎么学|学习计划|计划/.test(q))return '下一步建议：\n|顺序|动作|完成标准|\n|1|复盘最近错题|能说出错因|\n|2|补当前 Step 检查点|能留下截图或日志证据|\n|3|做一次迁移小题|能不看提示判断下一步|';if(/为什么.*详细|为什么.*标准|为什么.*简略|分层/.test(q))return '结论：当前 Step 使用“'+layer.level+'”。\n原因：'+layer.why+'\n证据：'+teacherEvidenceText().join('；')+'\n下一步：'+layer.next;if(/巩固题|出.*题|举一反三|练习/.test(q))return '给你 3 道客观巩固题：\n|题目|选项|答案|\n|1. 当前步骤出错时，最先确认什么？|A最终页面 B目标/现象/证据 C直接重做|B|\n|2. 哪些证据有助于复盘？|A日志 B截图 C“还是不行” D操作步骤|A、B、D|\n|3. 只看正确答案不解释错因，可以稳定迁移。|A对 B错|B|\n重点：做完后要能说出每题错因。';return ''}
function sendTeacherQuestion(text,auto){if(!text)return;var body=document.getElementById("__aix_teacher_body");teacherChat.push({role:'user',text:text});var local=localTeacherReply(text);if(local){teacherChat.push({role:'assistant',text:local});if(body)renderTeacherChat(body);return}teacherChat.push({role:'assistant',text:auto?'我正在把这个提醒转成可执行的小任务。':'我正在查看你的学习记录、最近错题和对话内容。'});if(body)renderTeacherChat(body);apiFetch('/profile/digital-twin/chat',{method:'POST',body:JSON.stringify({message:text})}).then(function(d){teacherChat.pop();teacherChat.push({role:'assistant',text:d.reply||d.answer||d.message||'我已经看过你的学习记录。建议先从最近错题涉及的知识点开始复盘，再回到当前 Step 做一次小验证。'});var b=document.getElementById("__aix_teacher_body");if(b)renderTeacherChat(b)}).catch(function(err){teacherChat.pop();teacherChat.push({role:'assistant',text:'我现在没能连上大模型。你可以先查看提醒和画像；如果要继续，我建议优先复盘最近 Quiz 的错题，再处理当前 Step 的检查清单。'});var b=document.getElementById("__aix_teacher_body");if(b)renderTeacherChat(b)})}

