var teacherSelectedTask=null
function teacherCard(title,body,accent){return '<section style="border:1px solid rgba(142,163,192,.16);border-left:3px solid '+(accent||'#57e3ff')+';background:rgba(12,22,38,.72);border-radius:18px;padding:15px 16px;min-width:0"><div style="font-size:14px;font-weight:950;color:#eaf3ff;margin-bottom:8px">'+title+'</div>'+body+'</section>'}
function teacherMiniMetric(label,value){return '<div style="border:1px solid rgba(142,163,192,.13);background:rgba(8,15,28,.48);border-radius:14px;padding:11px 12px"><div style="font-size:11px;color:#8ea3c0">'+escHtml(label)+'</div><div style="font-size:21px;font-weight:950;color:#eaf3ff;margin-top:3px">'+escHtml(value)+'</div></div>'}
